 "content": "def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    colors = [c for row in grid for c in row if c != bg]
    if not colors:
        return out
    fg = max(set(colors), key=colors.count)
    marker = 2
    h, w = len(grid), len(grid[0])
    # Fill missing cells lying between foreground pixels in each row or column.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == fg]
        if len(cs) >= 2:
            for c in range(min(cs), max(cs)+1):
                if grid[r][c] == bg: out[r][c] = marker
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == fg]
        if len(rs) >= 2:
            for r in range(min(rs), max(rs)+1):
                if grid[r][c] == bg: out[r][c] = marker
    # Close horizontal bottom/top edges of an outlined rectangular frame where vertical sides meet them.
    rows = [r for r in range(h) if fg in grid[r]]
    cols = [c for c in range(w) if any(grid[r][c] == fg for r in range(h))]
    r0, r1 = min(rows), max(rows)
    c0, c1 = min(cols), max(cols)
    for r in (r0, r1):
        for c in range(c0, c1+1):
            if grid[r][c] == bg: out[r][c] = marker
    return out
